package com.fdmultimedia.api.publishing.tiktok;
import com.fdmultimedia.api.auth.security.AuthenticatedUser; import jakarta.servlet.http.HttpServletResponse; import java.io.IOException; import java.net.*; import java.nio.charset.StandardCharsets; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/social-accounts/tiktok") public class TikTokOAuthController {private final TikTokAccountConnectionService service;public TikTokOAuthController(TikTokAccountConnectionService s){service=s;}
 @PostMapping("/connect") public TikTokConnectResponse connect(@AuthenticationPrincipal AuthenticatedUser p){return new TikTokConnectResponse(service.start(p));}
 @GetMapping("/callback") public void callback(@RequestParam(required=false)String state,@RequestParam(required=false)String code,@RequestParam(required=false)String error,HttpServletResponse response)throws IOException{TikTokCallbackResult r=service.callback(state,code,error);response.sendRedirect("/settings?"+(r.success()?"tiktok=connected":"tiktok=error&reason="+URLEncoder.encode(r.failureReason(),StandardCharsets.UTF_8)));}}
